actionConfiguration.body:
with deleted as (
	select *
	from public.set_contact_deleted(
		{{ appsmith.user.email }}::text,
		{{ Number(tblContacts.selectedRow.id || 0) }}::bigint,
		{{ appsmith.store.current_client_id }}::uuid,
		true
	)
)
select
    {{ Number(tblContacts.selectedRow.id || 0) }}::bigint as id,
    {{ tblContacts.selectedRow.contact_name }}::text as contact_name
from deleted;
